pub type Matrix<T> = Vec<Vec<T>>;

/// Broadcasts a vector `a` into a matrix of the specified `shape`.
/// 
/// # Parameters
/// - `a`: A vector of `i8` values to be broadcasted.
/// - `shape`: A vector of `u8` values representing the shape of the resulting matrix.
///
/// # Returns
/// A matrix of `i8` values with the specified shape, where the elements of `a` are replicated
/// according to the shape.
///
/// # Requires
/// - `shape` must have exactly two elements, representing the number of rows and columns.
/// - The length of `a` must be either equal to the number of rows or the number of columns.
/// 
/// # Ensures
/// - The resulting matrix has the shape specified by `shape`.
/// - Each row of the matrix is filled with the corresponding value from `a` based on its length.
fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Requires clause to ensure the shape is valid
    assert!(shape.len() == 2); // shape must have exactly two elements
    let r = shape[0] as usize; // Number of rows
    let c = shape[1] as usize; // Number of columns
    let len = a.len(); // Length of the input array

    // Initialize the matrix with the specified shape
    let mut matrix = vec![vec![0; c]; r];

    // Invariant: The matrix is initialized and has the correct dimensions
    // Decreases clause: The loop will terminate after r iterations
    if r == len {
        // Treat `a` as a column vector
        for i in 0..r {
            // Invariant: 0 <= i < r
            for j in 0..c {
                // Invariant: 0 <= j < c
                matrix[i][j] = a[i]; // Replicate the i-th element across the row
            }
        }
    } else {
        // Treat `a` as a row vector
        for i in 0..r {
            // Invariant: 0 <= i < r
            for j in 0..c {
                // Invariant: 0 <= j < c
                matrix[i][j] = a[j]; // Replicate the j-th element across the column
            }
        }
    }

    // Ensures clause to confirm the resulting matrix has the correct shape
    assert!(matrix.len() == r);
    assert!(matrix.iter().all(|row| row.len() == c));

    matrix
}

fn main() {
    // Example usage
    let a = vec![1, 2, 3];
    let shape = vec![3, 4];
    let result = broadcast(a, shape);
    
    for row in result {
        println!("{:?}", row);
    }
}